"use strict";(self.webpackChunk_otw_web_docusaurus=self.webpackChunk_otw_web_docusaurus||[]).push([[5408],{1872(a){a.exports=JSON.parse('{"title":"TTFB \ucd5c\uc801\ud654 \uac00\uc774\ub4dc","date":"2024-09-05","coverUrl":null,"html":"<h2 data-notion-block-id=\\"727fc4cc-799f-4801-bd38-9d339cf8d25a\\" id=\\"727fc4cc-799f-4801-bd38-9d339cf8d25a\\">TTFB \ucd5c\uc801\ud654 \uac00\uc774\ub4dc</h2><a href=\\"https://blog.sentry.io/how-to-make-your-web-page-faster-before-it-even-loads/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://blog.sentry.io/how-to-make-your-web-page-faster-before-it-even-loads/</a><p data-notion-block-id=\\"83a998ad-e183-4de9-bc1f-e0d395311868\\"><b>\uc2ec\uc724\uc12d</b>: TTFB\ub97c \uc5b4\ub5bb\uac8c \uce21\uc815\ud558\ub294\uc9c0, \uadf8\ub9ac\uace0 \uc5b4\ub5a4 \ubc29\uc2dd\uc73c\ub85c TTFB \uc18d\ub3c4\ub97c \ube60\ub974\uac8c \ud558\ub294\uc9c0 \uc124\uba85\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. web.dev\ud300\uc5d0\uc11c \uc81c\uacf5\ud558\ub294 <a href=\\"https://web.dev/learn/performance\\">\uc131\ub2a5 \ucd5c\uc801\ud654 \ubc30\uc6b0\uae30</a>\ub85c \ub300\ubd80\ubd84 \uc0c1\ud669\uc5d0\uc11c\uc758 \uc131\ub2a5 \uc774\uc288\ub97c \ud574\uacb0\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ud558\uc9c0\ub9cc TTFB\ub97c \ucd5c\uc801\ud654\ud558\ub294 \ubc29\ubc95\uc740 \uc0c1\ud669\uc5d0 \ub530\ub77c \uac08\ub9b4 \uc218 \uc788\ub294\ub370, \uc774 \uae00\uc744 \ud1b5\ud574 \ub300\ubd80\ubd84\uc758 \uacbd\uc6b0\ub97c \ud574\uacb0\ud560 \uc218 \uc788\uc744\uac81\ub2c8\ub2e4. \ubb3c\ub860 waterfall\uc774 \ubc1c\uc0dd\ud558\ub294 \uc9c0\uc810\uc774\ub098 \uce90\uc2dc\ud560 \uc9c0\uc810 \ucc3e\ub294 \uac83\uc740 \ubcf8\uc778\uc774 \ud574\uc57c\uaca0\uc9c0\ub9cc\uc694.</p><h2 data-notion-block-id=\\"0ee7c817-ded6-44d4-9a66-109ac2efe3d7\\" id=\\"0ee7c817-ded6-44d4-9a66-109ac2efe3d7\\">SSR \ub80c\ub354\ub9c1 \ubca4\uce58\ub9c8\ud06c</h2><a href=\\"https://blog.platformatic.dev/an-ssr-performance-showdown\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://blog.platformatic.dev/an-ssr-performance-showdown</a><p data-notion-block-id=\\"c03ac037-1bd0-4721-ad75-8297717c33a5\\"><b>\uc2ec\uc724\uc12d</b>: \ubcf5\uc7a1\ud55c \uacc4\uc0b0\uc774 \ub4e4\uc5b4\uc788\ub294 \ub80c\ub354\ub9c1\uc744 \uc5bc\ub9c8\ub098 \ube60\ub974\uac8c \ubc18\ud658\ud560 \uc218 \uc788\ub0d0\ub97c \uce21\uc815\ud55c \uc7ac\ubc0c\ub294 \ubca4\uce58\ub9c8\ud06c\uc785\ub2c8\ub2e4. React\uac00 \uc88b\uc9c0 \uc54a\ub294 \uc131\ub2a5\uc744 \uac00\uc9c0\uace0 \uc788\ub294 \uac83\uc740 \ub9ce\uc740 \uae00\uc5d0\uc11c \ud30c\uc545\ud560 \uc218 \uc788\uc9c0\ub9cc Vue\uac00 \uc88b\uc740 \uc131\ub2a5\uc744 \uac00\uc84c\ub2e4\ub294\uac83\uc740 \uc758\uc678\ub124\uc694. \ud558\uc9c0\ub9cc \uc0dd\ud0dc\uacc4\uc758 \uc131\uc219\ub3c4\uc640 \ubca4\uce58\ub9c8\ud06c\ub294 \uc0c1\ud669\uc5d0 \ub530\ub77c \ud06c\uac8c \uac08\ub9ac\ubbc0\ub85c \uc120\ud0dd\uc740 \ubcf8\uc778\uc5d0\uac8c \uc788\uc2b5\ub2c8\ub2e4 :)</p><p data-notion-block-id=\\"e42d4f99-2299-4b4d-a354-e66a566e33b5\\"><b>\uae40\ub300\uad00</b>:  SSR\uc758 \uc131\ub2a5\uc774 \ub6f0\uc5b4\ub098\uc9c0 \uc54a\ub2e4\uace0 \ud574\uc11c React\ub97c \ubc84\ub9ac\uace0 Vue\uac00 \ub354 \uc88b\ub2e4\uace0 Vue\uac00 \ubc14\ub85c \ub300\uccb4\ub418\uc9c0\ub294 \uc54a\uc744 \uac83 \uc785\ub2c8\ub2e4. \uc131\ub2a5\uc801\uc73c\ub85c \ucc38\uace0\ud55c\ub2e4\uba74 \uc88b\uc740 \ub0b4\uc6a9\uc774 \ub420 \uac70\ub77c\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"f1d589cb-ac24-40ae-98a9-c44c95a1ad75\\" id=\\"f1d589cb-ac24-40ae-98a9-c44c95a1ad75\\">Compound \ud328\ud134 \uc798 \ub9cc\ub4e4\uae30</h2><a href=\\"https://ivicabatinic.from.hr/posts/multipart-namespace-components-addressing-rsc-and-dot-notation-issues\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://ivicabatinic.from.hr/posts/multipart-namespace-components-addressing-rsc-and-dot-notation-issues</a><p data-notion-block-id=\\"087ed987-49e6-4bac-bab4-68a1d1bc42cd\\"><b>\uc2ec\uc724\uc12d</b>: Compound \ud328\ud134 \ucef4\ud3ec\ub10c\ud2b8\ub97c \ub9cc\ub4e4 \uacbd\uc6b0 \uc5ec\ub7ec \ud328\ud134\uc744 \ud1b5\ud574 export\ud558\uac8c \ub418\ub294\ub370, export/import \ubc29\uc2dd\uc744 \uc81c\ub300\ub85c \ud558\uc9c0 \uc54a\uc73c\uba74 \uc5ec\ub7ec\uac00\uc9c0 \ubb38\uc81c\uc5d0 \ubd80\ub52b\ud790 \uc218 \uc788\ub2e4\ub294 \uae00\uc785\ub2c8\ub2e4. Tree shaking\uc740 \ud504\ub860\ud2b8\uc5d4\ub4dc\uc5d0\uc11c \uc911\uc694\ud55c \uae30\uc220\uc774\ubbc0\ub85c \ubb34\uc5c7\uc778\uc9c0 \ud655\uc2e4\ud558\uac8c \uc778\uc9c0\ud558\uace0 \uc798 \uc0ac\uc6a9\ud558\uc2dc\uae38 \ubc14\ub78d\ub2c8\ub2e4(<a href=\\"https://ones-to-watch.ethansup.net/news/post/e118a44c46de44b79492998633298d32#a0608cf9-07a8-4413-95e5-f535e3811bff\\">Tree shaking\uc774 \ubb54\ub370</a>).</p><h2 data-notion-block-id=\\"c7f76ad2-2b96-4bed-a5f2-d6f954029ddb\\" id=\\"c7f76ad2-2b96-4bed-a5f2-d6f954029ddb\\"><code>blocking=\\"render\\"</code>\uac00 \ud558\ub294 \uc77c</h2><a href=\\"https://csswizardry.com/2024/08/blocking-render-why-whould-you-do-that/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://csswizardry.com/2024/08/blocking-render-why-whould-you-do-that/</a><p data-notion-block-id=\\"1388de79-fd91-4cbc-a253-b7369b8ab9c3\\"><b>\uc2ec\uc724\uc12d</b>: \uc544\uc9c1 \ubaa8\ub358 \ube0c\ub77c\uc6b0\uc800 \uc804\uccb4\uc5d0 \uc801\uc6a9\ub418\uc9c0 \uc54a\uc558\uc9c0\ub9cc \uace7 \uc801\uc6a9\ub420 <code>blocking=\\"render\\"</code>\uac00 \ubb34\uc5c7\uc778\uc9c0 \uc54c\uc544\ubcf4\uace0 \uc5b8\uc81c \ube0c\ub77c\uc6b0\uc800\uac00 \ud558\ub294 \uc77c\uc744 \ucc28\ub2e8\ud558\ub294\uc9c0\uc640 \ud568\uaed8 \uc54c\uc544\ubcf4\ub294 \uae00\uc785\ub2c8\ub2e4. \uc544\uc9c1 \ubaa8\ub358 \ube0c\ub77c\uc6b0\uc800\uc5d0 \ubaa8\ub450 \uad6c\ud604\ub418\uc9c0 \uc54a\uc558\uc9c0\ub9cc, parsing \ucc28\ub2e8\uacfc rendering \ucc28\ub2e8\uc744 \uc54c\uc544\ubcf4\ub294 \uac04\ub2e8\ud55c \uae00\uc785\ub2c8\ub2e4. <a href=\\"https://ones-to-watch.ethansup.net/news/post/a5902c7d-ee33-4db6-aaea-ea4820a7562f#f2bcbd5c-166a-41c4-b8f2-c765de5ab298\\"><code>&#x3C;script></code></a><a href=\\"https://ones-to-watch.ethansup.net/news/post/a5902c7d-ee33-4db6-aaea-ea4820a7562f#f2bcbd5c-166a-41c4-b8f2-c765de5ab298\\">\uc758 \uc791\ub3d9\ubc29\uc2dd</a>\ub3c4 \uac19\uc774 \ubcf4\uc2dc\ub294 \uac83\uc744 \ucd94\ucc9c\ub4dc\ub9bd\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"18d4adba-934c-4f5e-8cca-ada518da6e0a\\" id=\\"18d4adba-934c-4f5e-8cca-ada518da6e0a\\">JS \ucef4\ud30c\uc77c \ub3c4\uad6c\ub97c \ub9cc\ub4e4\uba74\uc11c JS \uc5d4\uc9c4 \uc54c\uc544\ubcf4\uae30</h2><a href=\\"https://cfallin.org/blog/2024/08/27/aot-js/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://cfallin.org/blog/2024/08/27/aot-js/</a><p data-notion-block-id=\\"9004d473-7c65-42e2-b285-ac2009556a79\\">JS \ucef4\ud30c\uc77c \ub3c4\uad6c\ub97c \ub9cc\ub4dc\ub294 \uacfc\uc815\uc744 \uc124\uba85\ud55c \uae00\uc774\uc9c0\ub9cc AOT\uc640 JIT\uc758 \ucc28\uc774\uc810\uacfc JS\uc758 \ud2b9\uc131 \uc911 \ud558\ub098\uc778 \uc778\ub77c\uc778 \uce90\uc2dc\ub97c \uc5ff\ubcfc \uc218 \uc788\uc73c\ubbc0\ub85c \uad00\uc2ec\uc788\ub294 \uc0ac\ub78c\uc740 \ubcf4\uc168\uc73c\uba74 \uc88b\uaca0\ub124\uc694. JS \uc5d4\uc9c4\uc758 JS \uc2e4\ud589 \ubc29\uc2dd\uc5d0 \ub300\ud55c \uc124\uba85\uc740 <a href=\\"https://www.youtube.com/watch?v=5nmpokoRaZI\\">JSConf\uc758 \uc601\uc0c1</a>\uc744 \uba3c\uc800 \ubcf4\uc2dc\uba74 \uc27d\uac8c \ub2e4\uac00\uac08 \uc218 \uc788\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"78d84f60-6cea-464a-aee5-a4e15dafaa88\\" id=\\"78d84f60-6cea-464a-aee5-a4e15dafaa88\\">(\ub7f0\ud0c0\uc784)CSS-in-JS\ub294 \uc65c \ub290\ub9b0\uac00\uc694?</h2><a href=\\"https://playfulprogramming.com/posts/why-is-css-in-js-slow\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://playfulprogramming.com/posts/why-is-css-in-js-slow</a><p data-notion-block-id=\\"c542e800-56f2-4139-8962-3c733dbc7fee\\">\uc774 \uae00\uc740 \ubca4\uce58\ub9c8\ud06c\ubcf4\ub2e4\ub294 \uc65c CSS-in-JS\uac00 \ub290\ub9b0\uc9c0 \uad6c\uc870\ub97c \ud1b5\ud574 \uc124\uba85\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \uc774\uc804\uc5d0 \uc18c\uac1c\ud588\ub358 \ubca4\uce58\ub9c8\ud06c(<a href=\\"https://ones-to-watch.ethansup.net/news/post/b6be5023-1604-4d2d-9f86-d1888a427413#03637a37-a07c-4a5f-9684-40ba0b57a1c9\\">SSR\uc5d0\uc11c Styled Components\ub294 \uc9c4\uc9dc \ub290\ub9ac\ub2e4.</a>)\ub3c4 \ub2e4\uc2dc \ubcf4\uc2dc\uba74 \uc88b\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"e53fab69-d976-45f9-a333-de7e98c3aa05\\" id=\\"e53fab69-d976-45f9-a333-de7e98c3aa05\\">RSC\uc640 \uc5d0\ub7ec\ud578\ub4e4\ub9c1</h2><a href=\\"https://edspencer.net/2024/7/16/errors-and-retry-with-react-server-components\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://edspencer.net/2024/7/16/errors-and-retry-with-react-server-components</a><p data-notion-block-id=\\"0ee75ed1-75db-4f69-806b-cdbd8b7d278b\\"><code>react-error-boundary</code>\uc5d0\uc11c <code>FallbackComponent</code>\uc5d0 \uc8fc\uc5b4\uc9c0\ub294 props\ub97c \ud65c\uc6a9\ud574\uc11c React Server Components\uc5d0\uc11c \ubc1c\uc0dd\ud55c \uc5d0\ub7ec\ub97c \ub2e4\uc2dc \uc2dc\ub3c4\ud558\ub294 \ubc29\uc2dd\uc744 \uc18c\uac1c\ud569\ub2c8\ub2e4. RSC\uc5d0 \uad00\ub828\ub41c \uc608\uc81c\uac00 \uc544\ub2c8\ub354\ub77c\ub3c4 <code>&#x3C;ErrorBoundary></code>\ub97c \uc798 \ud65c\uc6a9\ud558\ub294 \ubc29\ubc95\uc744 \uc18c\uac1c\ud558\ub2c8 \ud55c \ubc88 \uac00\ubccd\uac8c \ubcf4\uc2dc\uae38 \ucd94\ucc9c\ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"8adfd3b7-56e6-4fea-b1fe-a630a666878c\\" id=\\"8adfd3b7-56e6-4fea-b1fe-a630a666878c\\">WASM \uc2e4\uc0ac\ub840</h2><a href=\\"https://frontenddogma.com/posts/2024/5-wasm-use-cases-for-frontend-development/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://frontenddogma.com/posts/2024/5-wasm-use-cases-for-frontend-development/</a><p data-notion-block-id=\\"b757a37a-c665-48a2-80cf-65d5cce3ca26\\">WASM\uc744 \uc5b4\ub290 \uacf3\uc5d0 \uc0ac\uc6a9\ud560 \uc218 \uc788\ub294\uc9c0 \uc2e4 \uc0ac\ub840\ub97c \ud1b5\ud574 \uc54c\uc544\ubcf4\ub294 \uae00\uc785\ub2c8\ub2e4. \uc774\uc678\uc5d0\ub3c4 <a href=\\"https://www.notion.so/blog/how-we-sped-up-notion-in-the-browser-with-wasm-sqlite\\">Notion\uc758 SQLite + WASM\uc73c\ub85c \ub85c\uceec \ub370\uc774\ud130\ubca0\uc774\uc2a4 \uad6c\ucd95\ud558\uae30</a>, <a href=\\"https://www.figma.com/blog/webassembly-cut-figmas-load-time-by-3x/\\">Figma\uc758 WASM\uc744 \ud1b5\ud55c \ub80c\ub354\ub9c1 \uc5d4\uc9c4 \uad6c\ucd95</a>\ub3c4 \uc788\uc2b5\ub2c8\ub2e4 :)</p><h2 data-notion-block-id=\\"bbb60eaa-2d89-4317-95c2-def59104b39b\\" id=\\"bbb60eaa-2d89-4317-95c2-def59104b39b\\">\ubd84\ub9ac\ub294 \ucca0\uc800\ud558\uac8c</h2><a href=\\"https://alexkondov.com/interface-segregation-principle-in-react/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://alexkondov.com/interface-segregation-principle-in-react/</a><a href=\\"https://kyleshevlin.com/never-call-new-date-inside-your-components/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://kyleshevlin.com/never-call-new-date-inside-your-components/</a><p data-notion-block-id=\\"23d07338-2611-4305-9493-d3674f999fb8\\">\uc804\uc790\ub294 \uc778\ud130\ud398\uc774\uc2a4 \ubd84\ub9ac \uc6d0\uce59\uc774 React\uc5d0 \uc801\uc6a9\ub418\ub294 \ubd80\ubd84\uc744 \uc124\uba85\ud55c \uae00\uc774\uace0, \ud6c4\uc790\ub294 \uc7ac\uc0ac\uc6a9\ub418\ub294 \ucef4\ud3ec\ub10c\ud2b8\uc5d0\uc11c \uae30\ubcf8 \uac12\uc744 \uc678\ubd80\uc5d0\uc11c \uc124\uc815\ud560 \uc218 \uc788\ub3c4\ub85d \ub3d5\ub294 \uac83\uc744 \uad8c\uc7a5\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \ub458 \ub2e4 \ubd84\ub9ac\uc5d0 \uad00\ud55c \uad00\uc810\uc744 \uc124\uba85\ud558\ub294 \uae00\uc774\ub77c\uc11c \uac00\ubccd\uac8c \ubcf4\uae30 \uc88b\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"5305d247-0b9f-4962-b1dd-aa921534dbf4\\" id=\\"5305d247-0b9f-4962-b1dd-aa921534dbf4\\">Toast\ub294 \uc88b\uc740 UX\ub97c \uc81c\uacf5\ud558\ub098\uc694?</h2><a href=\\"https://maxschmitt.me/posts/toasts-bad-ux\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://maxschmitt.me/posts/toasts-bad-ux</a><p data-notion-block-id=\\"1cd6caf8-cc68-4623-af74-30369f530664\\">\uac04\ub2e8\ud55c \uc608\uc81c\uc640 \ud568\uaed8 \ub9ce\uc774 \uc0ac\uc6a9\ud558\ub294 Toast UI\uac00 (\uc801\uc5b4\ub3c4 PC\uc5d0\uc11c\ub294) \uc88b\uc740 UX\uac00 \uc544\ub2d0 \uc218\ub3c4 \uc788\ub2e4\ub294 \uac04\ub2e8\ud55c \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"b299cd18-fe96-4085-9cfa-392264c86c3d\\" id=\\"b299cd18-fe96-4085-9cfa-392264c86c3d\\">CSS \uba85\uc2dc\ub3c4 \uc18d\uc784\uc218</h2><a href=\\"https://cirrus.twiddles.com/blog/2024/08/21/double-your-specificity-with-this-one-weird-trick/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://cirrus.twiddles.com/blog/2024/08/21/double-your-specificity-with-this-one-weird-trick/</a><p data-notion-block-id=\\"e7a0f9a5-5475-4191-813d-887eb16db46f\\">\uac04\ub2e8\ud558\uac8c CSS \uba85\uc2dc\ub3c4\ub97c \ub192\uc774\uace0 \uc2f6\uc744 \ub54c \uc0ac\uc6a9\ub418\ub294 \ud2b8\ub9ad\uc785\ub2c8\ub2e4.</p>"}')}}]);